namespace RonSijm.FluidHumidifier.Factories.Logs;

public class InnerTransformerProcessorFactory(Action<Humidifier.Logs.TransformerTypes.Processor> factoryAction = null) : SubResourceFactory<Humidifier.Logs.TransformerTypes.Processor>
{

    internal InnerTransformerParseCloudfrontFactory ParseCloudfrontFactory { get; set; }

    internal InnerTransformerLowerCaseStringFactory LowerCaseStringFactory { get; set; }

    internal InnerTransformerUpperCaseStringFactory UpperCaseStringFactory { get; set; }

    internal InnerTransformerDeleteKeysFactory DeleteKeysFactory { get; set; }

    internal InnerTransformerRenameKeysFactory RenameKeysFactory { get; set; }

    internal InnerTransformerGrokFactory GrokFactory { get; set; }

    internal InnerTransformerSplitStringFactory SplitStringFactory { get; set; }

    internal InnerTransformerCsvFactory CsvFactory { get; set; }

    internal InnerTransformerAddKeysFactory AddKeysFactory { get; set; }

    internal InnerTransformerSubstituteStringFactory SubstituteStringFactory { get; set; }

    internal InnerTransformerParseKeyValueFactory ParseKeyValueFactory { get; set; }

    internal InnerTransformerParseWAFFactory ParseWAFFactory { get; set; }

    internal InnerTransformerParseVPCFactory ParseVPCFactory { get; set; }

    internal InnerTransformerParseRoute53Factory ParseRoute53Factory { get; set; }

    internal InnerTransformerTypeConverterFactory TypeConverterFactory { get; set; }

    internal InnerTransformerParseJSONFactory ParseJSONFactory { get; set; }

    internal InnerTransformerParsePostgresFactory ParsePostgresFactory { get; set; }

    internal InnerTransformerCopyValueFactory CopyValueFactory { get; set; }

    internal InnerTransformerMoveKeysFactory MoveKeysFactory { get; set; }

    internal InnerTransformerDateTimeConverterFactory DateTimeConverterFactory { get; set; }

    internal InnerTransformerTrimStringFactory TrimStringFactory { get; set; }

    internal InnerTransformerListToMapFactory ListToMapFactory { get; set; }

    protected override Humidifier.Logs.TransformerTypes.Processor Create()
    {
        var processorResult = CreateProcessor();
        factoryAction?.Invoke(processorResult);

        return processorResult;
    }

    private Humidifier.Logs.TransformerTypes.Processor CreateProcessor()
    {
        var processorResult = new Humidifier.Logs.TransformerTypes.Processor();

        return processorResult;
    }
    public override void CreateChildren(Humidifier.Logs.TransformerTypes.Processor result)
    {
        base.CreateChildren(result);

        result.ParseCloudfront ??= ParseCloudfrontFactory?.Build();
        result.LowerCaseString ??= LowerCaseStringFactory?.Build();
        result.UpperCaseString ??= UpperCaseStringFactory?.Build();
        result.DeleteKeys ??= DeleteKeysFactory?.Build();
        result.RenameKeys ??= RenameKeysFactory?.Build();
        result.Grok ??= GrokFactory?.Build();
        result.SplitString ??= SplitStringFactory?.Build();
        result.Csv ??= CsvFactory?.Build();
        result.AddKeys ??= AddKeysFactory?.Build();
        result.SubstituteString ??= SubstituteStringFactory?.Build();
        result.ParseKeyValue ??= ParseKeyValueFactory?.Build();
        result.ParseWAF ??= ParseWAFFactory?.Build();
        result.ParseVPC ??= ParseVPCFactory?.Build();
        result.ParseRoute53 ??= ParseRoute53Factory?.Build();
        result.TypeConverter ??= TypeConverterFactory?.Build();
        result.ParseJSON ??= ParseJSONFactory?.Build();
        result.ParsePostgres ??= ParsePostgresFactory?.Build();
        result.CopyValue ??= CopyValueFactory?.Build();
        result.MoveKeys ??= MoveKeysFactory?.Build();
        result.DateTimeConverter ??= DateTimeConverterFactory?.Build();
        result.TrimString ??= TrimStringFactory?.Build();
        result.ListToMap ??= ListToMapFactory?.Build();
    }

} // End Of Class

